import random

class MusicPlayer:
    MIN_VOLUME = 0
    MAX_VOLUME = 100

    def __init__(self):
        self._playlist = []
        self._current_song = None
        self._volume = 50

    @property
    def playlist(self):
        return self._playlist.copy()

    @property
    def current_song(self):
        return self._current_song

    @property
    def volume(self):
        return self._volume

    @volume.setter
    def volume(self, value):
        self._volume = value

    def add_song(self, song):
        self._playlist.append(song)

    def remove_song(self, song):
        if song in self._playlist:
            self._playlist.remove(song)
            if self._current_song == song:
                self.stop()

    def play(self):
        if self._playlist and self._current_song:
            return self._playlist[0]
        elif len(self._playlist):
            return False

    def stop(self):
        if self._current_song:
            self._current_song = None
            return True
        else:
            return False

    def switch_song(self):
        if self._current_song:
            current_index = self._get_current_song_index()
            if current_index < len(self._playlist) - 1:
                self._current_song = self._playlist[current_index + 1]
                return True
            else:
                return False
        else:
            return False

    def previous_song(self):
        if self._current_song:
            current_index = self._get_current_song_index()
            if current_index > 0:
                self._current_song = self._playlist[current_index - 1]
                return True
            else:
                return False
        else:
            return False

    def set_volume(self, volume):
        if self.MIN_VOLUME <= volume <= self.MAX_VOLUME:
            self._volume = volume
        else:
            return False

    def shuffle(self):
        if self._playlist:
            random.shuffle(self._playlist)
            return True
        else:
            return False

    def _get_current_song_index(self):
        return self._playlist.index(self._current_song)
